# 1 coin = 1 kr when spent, so packages cost about 1 kr per coin with a small bonus on bigger ones.
PACKAGES = [(100, 100, ""), (260, 250, "+4% bonus"), (550, 500, "+10% bonus"), (1150, 1000, "+15% bonus")]  # coins, kr, note


def to_coins(apps, schema_editor):
    Product = apps.get_model("core", "Product")
    Product.objects.filter(kind="diamonds").update(is_active=False)
    for order, (coins, kr, note) in enumerate(PACKAGES):
        Product.objects.update_or_create(code=f"coins-{coins}", defaults={
            "kind": "diamonds", "diamonds": coins, "name": f"{coins} coins", "description": note, "tier": "basic",
            "days": 30, "price": kr * 100, "currency": "DKK", "is_active": True, "sort_order": order})
    for model, fields in (("DiamondTransaction", ["reason"]), ("Frame", ["description"]), ("Offer", ["title", "text"])):
        for obj in apps.get_model("core", model).objects.all():
            changed = False
            for f in fields:
                v = getattr(obj, f) or ""
                nv = v.replace("Diamonds", "Coins").replace("diamonds", "coins").replace("Diamond", "Coin").replace("diamond", "coin")
                if nv != v:
                    setattr(obj, f, nv)
                    changed = True
            if changed:
                obj.save(update_fields=fields)


